schema_delta:
ONE migration: backend/prisma/migrations/20261014090000_tax_decisions/migration.sql (additive only).

model Order {
  // + Own-fleet delivery fee BEFORE GST (owner 2026-10-13, H9). Per-ticket -> INT4. 0 on legacy orders (no backfill).
  deliveryFeeCents    Int @default(0)
  // + GST on that fee at the order's tender rate. Part of taxCents (taxCents = food GST + this).
  deliveryFeeTaxCents Int @default(0)
}

model TaxInvoice {
  // + Delivery charge before GST: in taxableValueCents and totalCents, plus its own TaxInvoiceLine.
  deliveryFeeCents Int @default(0)
}

model GiftCard {
  // + Value taken to breakage (4200 sold / 6060 promotional) by expiry or a sold-card forfeit. INT4 (card <= PKR 100k).
  breakageCents Int       @default(0)
  breakageAt    DateTime?
}

model Supplier {
  // + Income-tax filer status for withholding (ATL): filer | non_filer | exempt | unknown
  filerStatus         String    @default("unknown")
  whtExemptCertNo     String?
  whtExemptUntil      DateTime?
  // + Who usually charges us sales tax: fbr | srb | pra | kpra | bra (pre-fills a bill / OpEx payment)
  defaultTaxAuthority String?
  // + Usual WHT section: 153_1_a | 153_1_b | 153_1_c | 155 | none
  defaultWhtSection   String?
  opexLines           OpexLine[]
}

model SupplierBill {
  // + Authority that charged the bill's sales tax. Decides the input account (1320/1321-1324). Default 'fbr' = today's 1320.
  taxAuthority String  @default("fbr")
  // + Snapshot of how whtCents was worked out.
  whtSection   String?
  whtRateBps   Int?
}

model OpexLine {
  // + The vendor (a Supplier of the CATEGORY's company). Required for WHT.
  supplierId        String?
  whtSection        String?  // 153_1_a | 153_1_b | 153_1_c | 155 | null = none
  inputTaxAuthority String?  // fbr | srb | pra | kpra | bra
  supplier          Supplier? @relation(fields: [supplierId], references: [id], onDelete: SetNull)
  @@index([supplierId])
}

model OpexPayment {
  // + actualCents stays the CASH that left the bank. invoice = actualCents + whtCents.
  inputTaxCents     BigInt  @default(0)
  inputTaxAuthority String?
  whtCents          BigInt  @default(0)
  whtSection        String?
  whtRateBps        Int?
  filerStatus       String? // snapshot at payment
  whtOverrideReason String?
}

model OperationsConfig {
  // + { '153_1_a': {filerBps, nonFilerBps}, '153_1_b': …, '153_1_c': …, '155': … }. null = defaults (lib/withholding.ts), with withholdingTaxPct as the 153_1_a filer rate.
  withholdingRates Json?
  // + { enabled, payoutBankAccountId, mdrBps, feeTaxBps, lagDays, toleranceBps, maxBatchDays, maxFeeBps, startDay }. null = disabled.
  cardSettlement   Json?
}

model SalesTaxPayment {
  // + Sales tax withheld by customers (1335) set off against this authority's output in this payment.
  customerWithheldSetOffCents BigInt @default(0)
}

model ReceivablePayment {
  // + For method 'stwh' (sales tax withheld by the client): the authority it was withheld for (fbr | srb | pra | kpra | bra).
  taxAuthority String?
}

// NEW, company data
model CardSettlement {
  id              String   @id @default(uuid())
  tenantId        String
  bankAccountId   String
  statementLineId String
  journalEntryId  String?
  grossCents      BigInt
  feeCents        BigInt
  feeTaxCents     BigInt   @default(0) // informational split of feeCents (all of it is 6080, H12)
  netCents        BigInt
  dayFrom         String   // YYYY-MM-DD PKT
  dayTo           String
  status          String   // auto | confirmed
  createdById     String?
  createdAt       DateTime @default(now())
  days            CardSettlementDay[]
  @@unique([tenantId, statementLineId])
  @@index([tenantId, dayTo])
  @@map("card_settlements")
}

model CardSettlementDay {
  id           String   @id @default(uuid())
  tenantId     String
  settlementId String
  day          String   // YYYY-MM-DD PKT
  grossCents   BigInt
  settlement   CardSettlement @relation(fields: [settlementId], references: [id], onDelete: Cascade)
  @@unique([tenantId, day])
  @@index([settlementId])
  @@map("card_settlement_days")
}
(An undo deletes the CardSettlement, cascading its days, after reversing its entry. A re-post of the same line uses sourceId '<lineId>@n'.)

SQL-only parts (same DO $do$ guard pattern as 20261013150000):
- ALTER TABLE card_settlements / card_settlement_days ENABLE ROW LEVEL SECURITY.
- CREATE POLICY card_settlements_rls / card_settlement_days_rls FOR ALL USING (app_is_service_mode() OR "tenantId" = ANY(app_tenant_ids())) WITH CHECK (same).
- FKs: card_settlement_days.settlementId -> card_settlements ON DELETE CASCADE; opex_lines.supplierId -> suppliers ON DELETE SET NULL.
- No partial unique indexes. No backfill UPDATEs: every new column has a safe default. Legacy orders keep fee 0 by design.
The CapEx columns (CapexLine.supplierId / inputTaxCents / inputTaxCode, CapexPayment.whtCents) are NOT in this delta. The FA/CapEx area owns them (see shared_file_changes contract).
